fn interleave_vectors(vec1: &[i32], vec2: &[i32]) -> Vec<i32> {
    let mut result = Vec::new();
    let size = vec1.len().max(vec2.len());
    for i in 0..size {
        if i < vec1.len() { result.push(vec1[i]); }
        if i < vec2.len() { result.push(vec2[i]); }
    }
    result
}

