    s.chars()
     .map(|c| {
         if c.is_alphabetic() {
             let new_c = if capitalize { c.to_ascii_uppercase() } else { c.to_ascii_lowercase() };
             capitalize = !capitalize;
             new_c
         } else {
             c
         }
     })
     .collect()
}

