fn quick_sort(arr: &mut [i32]) {
    if arr.len() > 1 {
        let pivot_index = arr.len() - 1;
        let pivot = arr[pivot_index];
        let mut i = 0;

        for j in 0..pivot_index {
            if arr[j] < pivot {
                arr.swap(i, j);
                i += 1;
            }
        }

        arr.swap(i, pivot_index);

        quick_sort(&mut arr[0..i]);
        quick_sort(&mut arr[i+1..]);
    }
}

fn main() {
    let mut arr = [10, 7, 8, 9, 1, 5];
    quick_sort(&mut arr);
    println!("{:?}", arr);
}
```

