use std::fmt::Debug;

// Custom vector implementation in Rust
struct GenericMyVector<DT> {
    arr: Vec<DT>,
}

impl<DT> GenericMyVector<DT> {
    // Constructor to initialize the vector
    fn new() -> Self {
        GenericMyVector { arr: Vec::new() }
    }

    // Function to push an element to the vector
    fn push_back(&mut self, data: DT) -> usize {
        self.arr.push(data);
        self.arr.len()
    }

    // Function to pop an element from the vector
    fn pop_back(&mut self) -> Option<DT> {
        self.arr.pop()
    }

    // Function to return the size of the vector
    fn size(&self) -> usize {
        self.arr.len()
    }

    // Function to get a reference to an element at a given index
    fn get(&self, index: usize) -> Option<&DT> {
        self.arr.get(index)
    }

    // Function to iterate over the vector
    fn iter(&self) -> std::slice::Iter<DT> {
        self.arr.iter()
    }
}

// Function to display the elements of the vector
fn display_vector<T: Debug>(v: &GenericMyVector<T>) {
    for element in v.iter() {
        print!("{:?} ", element);
