int determinant(int matrix[4][4], int n){
        int det = 0;
        int submatrix[4][4];

        if(n == 1){
                return matrix[0][0];
        }
        else if(n == 2){
                return ((matrix[0][0] * matrix[1][1]) - (matrix[1][0] * matrix[0][1]));
        }
        else{
