    next: Option<Box<Node>>,
}

impl Node {
    fn new(val: i32) -> Self {
        Self { data: val, next: None }
    }
}

fn reverse_list(mut head: Option<Box<Node>>) -> Option<Box<Node>> {
    let mut prev = None;

    while let Some(mut current) = head {
        head = current.next.take();
        current.next = prev;
        prev = Some(current);
    }

    prev
}

